# Retired gallery assets must not return during regeneration or ship in dist.
REMOVED_ICONS={'video','headphones','joystick','folder','water','atmosphere','precipitation','editor-navigation-mesh','editor-turn-signal','editor-reading-light','editor-ambient-light','editor-vehicle-headlight','editor-reverse-light'}
REMOVED_ICONS.update({
    'editor-navigation-agent',
    'drawing-compass', 'paint-palette', 'video-slate', 'cinema',
    'film-reel', 'document-bundle', 'file-folder', 'retro-tv',
    'light-spot-3d', 'light-area-3d', 'light-directional-3d',
    'light-point-3d', 'light-led-strip-3d', 'light-led-bulb-3d',
})
REMOVED_ICONS.update({'light-incandescent-3d','light-low-beam-2d','light-low-beam-3d','light-fog-2d','light-fog-3d','light-spot-2d','light-directional-2d'})
REMOVED_ICONS.update({'light-high-beam-2d','light-high-beam-3d','graphics-card-3d','light-led-bulb-2d','editor-led-bulb','editor-camera','editor-keyframe','editor-rigid-body','editor-script','editor-visual-script','editor-terrain','editor-foliage','editor-hierarchy'})
