REMOVED_ICONS.update({'weather-frost-ice','editor-directional-light','light-led-strip-2d'})
for retired in REMOVED_ICONS:
    (ROOT/'custom-icons'/f'{retired}.svg').unlink(missing_ok=True)
    (ROOT/'dist/custom-icons'/f'{retired}.svg').unlink(missing_ok=True)
def icon(id,name,group,description,defs,body):
    if id in REMOVED_ICONS:
        return
    if id in REVISIONS:
        description,defs,body=REVISIONS[id]
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="none" role="img" aria-labelledby="{id}-title"><title id="{id}-title">{name} — custom SVG icon</title><defs>{defs}</defs>{body}</svg>'
    icons.append(dict(id=id,name=name,group=group,description=description,svg=svg))
    (ROOT/'custom-icons'/f'{id}.svg').write_text(svg)

